for q in "$@"; do echo "## $q"; curl -s -A "quizcollect/1.0" -G "https://ko.wikipedia.org/w/api.php" --data-urlencode "action=query" --data-urlencode "list=search" --data-urlencode "srsearch=$q" --data-urlencode "srlimit=3" --data-urlencode "format=json" | node -e 'let s="";process.stdin.on("data",d=>s+=d).on("end",()=>{try{console.log(JSON.parse(s).query.search.map(x=>x.title).join(" | "))}catch(e){console.log("ERR",s.slice(0,100))}})'; sleep 1; done
